import { computed, type ComputedRef } from 'vue'
import { useState } from '#imports'
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore virtual module generated by this module's `setup()`
import { useUserPreferences, useUserSession } from '#dashboard/optional'
import type { DashboardLayout } from '../../../types'
import { normalizeLayout } from '../../shared/layout'

type Layouts = Record<string, DashboardLayout>

export interface DashboardLayoutState {
  /** The user's layout of this dashboard: this session's changes, else the saved preference, else the default. */
  layout: ComputedRef<DashboardLayout>
  /** Whether changes are saved for the user (Preferences installed and signed in), not only for this session. */
  persisted: ComputedRef<boolean>
  /** Applies a change, then saves it as the user's preference when it can. */
  update: (change: (layout: DashboardLayout) => DashboardLayout) => Promise<void>
}

/**
 * The per-user layout of one dashboard. With `@frigear-nu/preferences` and a signed-in user it is the
 * `dashboardLayouts` preference; otherwise it lives in `useState` for the session and the registered default applies
 * again on reload.
 */
export function useDashboardLayout(name: string): DashboardLayoutState {
  // Changes made in this session, by dashboard name. They win over the stored preference until the next reload.
  const session = useState<Layouts>('dashboard:layouts', () => ({}))
  const preferences = useUserPreferences?.()
  const userSession = useUserSession?.()

  const saved = computed<Layouts>(() => (preferences?.preferences.value?.dashboardLayouts ?? {}) as Layouts)
  const persisted = computed(() => !!preferences && !!userSession?.loggedIn.value)
  const layout = computed(() => normalizeLayout(session.value[name] ?? saved.value[name]))

  async function update(change: (layout: DashboardLayout) => DashboardLayout) {
    const next = normalizeLayout(change(layout.value))
    session.value = { ...session.value, [name]: next }
    if (!persisted.value) return
    await preferences!.set('dashboardLayouts', { ...saved.value, [name]: next })
  }

  return { layout, persisted, update }
}
